<?php

declare(strict_types=1);

namespace Magento\UrlRewrite\Service\V1\Data;

use Magento\Framework\Serialize\Serializer\Json;

// The real factory is generated by Magento at compile time and does not exist in a bare checkout.
if (!class_exists(UrlRewriteFactory::class, false)) {
    class UrlRewriteFactory
    {
        /**
         * @param array<string, mixed> $data
         */
        public function create(array $data = []): UrlRewrite
        {
            return new UrlRewrite($data, new Json());
        }
    }
}
